const here = position();
if (inventory_count('cobblestone') < 4) {
  const opened = await open_chest();
  if (!opened.ok) {
    return { done: false, detail: opened.detail };
  }
  const took = await withdraw('cobblestone', 4);
  if (!took.ok) {
    return { done: false, detail: took.detail };
  }
}
for (let i = 0; i < 4; i++) {
  await place('cobblestone', here.x + i, here.y, here.z);
}
return { done: true, detail: 'laid four cobblestone' };
